*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --z-blue:    #1B1DB5;
  --z-blue-dk: #13158A;
  --z-cyan:    #00A8FF;
  --z-black:   #000000;
  --z-white:   #FFFFFF;
  --z-gray:    #F4F5F9;
  --z-gray2:   #E8EAF2;
  --z-muted:   #6B7280;
  --z-text:    #0D0E2A;
  --font: 'Nunito Sans', system-ui, sans-serif;
  --radius: 6px;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font);
  color: var(--z-text);
  background: var(--z-white);
  line-height: 1.65;
  overflow-x: hidden;
}

/* NAV */
nav {
  position: fixed; top: 0; left: 0; right: 0; z-index: 200;
  background: var(--z-white);
  border-bottom: 1px solid var(--z-gray2);
  padding: 0 5vw;
  height: 64px;
  display: flex; align-items: center; justify-content: space-between;
  transition: box-shadow 0.3s;
}
nav.scrolled { box-shadow: 0 2px 24px rgba(27,29,181,0.08); }

.logo { display: flex; align-items: center; gap: 10px; text-decoration: none; }
.logo-badge {
  width: 40px; height: 40px;
  background: var(--z-blue);
  border-radius: 4px;
  display: flex; align-items: center; justify-content: center;
  position: relative; overflow: hidden;
}
.logo-badge::after {
  content: '';
  position: absolute;
  bottom: -6px; left: -4px; right: -4px;
  height: 16px;
  background: var(--z-black);
  border-radius: 50% 50% 0 0 / 100% 100% 0 0;
}
.logo-text { font-size: 1.1rem; font-weight: 900; letter-spacing: 0.12em; color: var(--z-white); position: relative; z-index: 1; }
.logo-name { font-weight: 700; font-size: 1.05rem; color: var(--z-blue); letter-spacing: 0.04em; }
.logo-sub { font-size: 0.7rem; color: var(--z-muted); font-weight: 400; letter-spacing: 0.05em; display: block; line-height: 1; }
.nav-cta {
  background: var(--z-blue);
  color: var(--z-white);
  padding: 0.6rem 1.6rem;
  border-radius: var(--radius);
  font-family: var(--font);
  font-size: 0.85rem; font-weight: 700;
  text-decoration: none; letter-spacing: 0.03em;
  transition: background 0.2s;
}
.nav-cta:hover { background: var(--z-blue-dk); }

/* HERO */
.hero {
  padding: 100px 5vw 0;
  background: linear-gradient(rgba(10,12,40,0.72), rgba(10,12,40,0.65)), url('data:image/jpeg;base64,') center/cover no-repeat;
  min-height: 100vh;
  display: flex; flex-direction: column; justify-content: center;
  position: relative; overflow: hidden;
}
.hero-inner {
  max-width: 1200px; margin: 0 auto; width: 100%;
  display: grid; grid-template-columns: 55% 45%;
  align-items: center; gap: 3rem; padding-bottom: 5rem;
}
.hero-kicker {
  display: inline-flex; align-items: center; gap: 8px;
  background: rgba(27,29,181,0.07);
  border: 1px solid rgba(27,29,181,0.15);
  padding: 0.35rem 0.9rem; border-radius: 100px;
  font-size: 0.72rem; font-weight: 700;
  letter-spacing: 0.14em; text-transform: uppercase;
  color: var(--z-blue); margin-bottom: 1.6rem;
}
.kicker-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--z-cyan); }

.hero h1 {
  font-size: clamp(2.6rem, 4.8vw, 4rem); font-weight: 900;
  line-height: 1.08; letter-spacing: -0.02em;
  color: var(--z-text); margin-bottom: 1.4rem;
}
.hero h1 .hl {
  color: var(--z-blue); position: relative;
}
.hero h1 .hl::after {
  content: ''; position: absolute;
  bottom: 2px; left: 0; right: 0;
  height: 3px; background: var(--z-cyan); border-radius: 2px;
}
.hero-desc { font-size: 1.05rem; color: var(--z-muted); max-width: 500px; margin-bottom: 2.4rem; line-height: 1.8; }
.hero-btns { display: flex; gap: 1rem; flex-wrap: wrap; }
.btn-blue {
  background: var(--z-blue); color: var(--z-white);
  padding: 0.9rem 2rem; border-radius: var(--radius);
  font-size: 0.9rem; font-weight: 700; text-decoration: none;
  transition: background 0.2s, transform 0.15s; border: none; cursor: pointer; font-family: var(--font);
}
.btn-blue:hover { background: var(--z-blue-dk); transform: translateY(-1px); }
.btn-outline {
  background: transparent; color: var(--z-blue);
  padding: 0.9rem 2rem; border-radius: var(--radius);
  font-size: 0.9rem; font-weight: 600; text-decoration: none;
  border: 1.5px solid var(--z-blue); transition: background 0.2s;
}
.btn-outline:hover { background: rgba(27,29,181,0.05); }
.hero-trust {
  display: flex; align-items: center; gap: 1rem;
  margin-top: 2rem; font-size: 0.78rem; color: var(--z-muted);
}
.trust-sep { width: 1px; height: 16px; background: var(--z-gray2); }
.hero-trust strong { color: var(--z-text); font-weight: 700; }

.hero-visual { position: relative; }
.hero-card-main {
  background: var(--z-blue); border-radius: 16px;
  padding: 3rem 2.5rem; color: var(--z-white);
  position: relative; overflow: hidden;
}
.hero-card-main::before {
  content: ''; position: absolute;
  bottom: -60px; left: -40px;
  width: 280px; height: 280px; border-radius: 50%;
  background: rgba(0,168,255,0.15);
}
.hero-badge-z {
  font-size: 4rem; font-weight: 900; letter-spacing: -0.05em;
  opacity: 0.1; line-height: 1; margin-bottom: 1.5rem; position: relative; z-index: 1;
}
.hero-card-title { font-size: 1.4rem; font-weight: 700; line-height: 1.3; margin-bottom: 0.6rem; position: relative; z-index: 1; }
.hero-card-sub { font-size: 0.85rem; opacity: 0.75; position: relative; z-index: 1; margin-bottom: 1.8rem; }
.hero-card-stat { display: flex; gap: 2rem; position: relative; z-index: 1; }
.h-stat-num { font-size: 1.8rem; font-weight: 900; display: block; color: var(--z-cyan); }
.h-stat-label { font-size: 0.72rem; opacity: 0.7; text-transform: uppercase; letter-spacing: 0.1em; }

.hero-float {
  position: absolute; background: var(--z-white);
  border-radius: 10px; padding: 0.8rem 1.1rem;
  box-shadow: 0 8px 32px rgba(27,29,181,0.15);
  font-size: 0.78rem;
}
.hero-float strong { display: block; font-weight: 700; color: var(--z-text); font-size: 0.82rem; }
.hero-float span { color: var(--z-muted); }
.float-1 { top: -16px; right: 24px; }
.float-2 { bottom: -16px; left: -20px; }

/* STRIP */
.blue-strip { background: var(--z-blue); }
.strip-inner {
  max-width: 1200px; margin: 0 auto;
  display: grid; grid-template-columns: repeat(4,1fr);
}
.strip-item {
  padding: 2rem 2.5rem;
  border-right: 1px solid rgba(255,255,255,0.12);
  color: var(--z-white);
}
.strip-item:last-child { border-right: none; }
.strip-num { font-size: 2rem; font-weight: 900; display: block; color: var(--z-cyan); line-height: 1; margin-bottom: 4px; }
.strip-label { font-size: 0.78rem; opacity: 0.75; }

/* SECTIONS */
section { padding: 6rem 5vw; }
.sec-inner { max-width: 1200px; margin: 0 auto; }
.kicker-tag { font-size: 0.72rem; font-weight: 700; letter-spacing: 0.16em; text-transform: uppercase; color: var(--z-blue); margin-bottom: 0.8rem; }
.sec-title { font-size: clamp(1.8rem, 3vw, 2.6rem); font-weight: 900; line-height: 1.15; letter-spacing: -0.02em; margin-bottom: 1rem; }
.sec-desc { font-size: 1rem; color: var(--z-muted); line-height: 1.8; max-width: 540px; }

/* PROBLEMA */
.problema { background: var(--z-gray); }
.prob-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 4rem; align-items: center; }
.prob-items { margin-top: 2.5rem; display: flex; flex-direction: column; gap: 1.2rem; }
.prob-item {
  background: var(--z-white); border-radius: 10px;
  border: 1px solid var(--z-gray2); padding: 1.2rem 1.4rem;
  display: flex; gap: 1rem; align-items: flex-start;
  transition: border-color 0.2s, box-shadow 0.2s;
}
.prob-item:hover { border-color: rgba(27,29,181,0.2); box-shadow: 0 4px 20px rgba(27,29,181,0.06); }
.prob-icon { width: 38px; height: 38px; border-radius: 8px; background: rgba(27,29,181,0.08); display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-size: 1rem; }
.prob-item h4 { font-size: 0.92rem; font-weight: 700; margin-bottom: 3px; }
.prob-item p { font-size: 0.84rem; color: var(--z-muted); line-height: 1.6; }

.prob-quote {
  background: var(--z-blue); border-radius: 16px;
  padding: 2.5rem; color: var(--z-white); position: relative; overflow: hidden;
}
.prob-quote::before {
  content: '"'; position: absolute; top: -20px; left: 20px;
  font-size: 10rem; font-weight: 900; opacity: 0.07; line-height: 1;
}
.prob-q-text { font-size: 1.25rem; font-weight: 600; line-height: 1.5; margin-bottom: 1.5rem; position: relative; }
.prob-q-text em { color: var(--z-cyan); font-style: normal; }
.prob-author { display: flex; align-items: center; gap: 0.8rem; }
.prob-avatar { width: 42px; height: 42px; border-radius: 50%; background: rgba(255,255,255,0.15); display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 0.85rem; }
.prob-name { font-size: 0.85rem; font-weight: 700; }
.prob-role { font-size: 0.78rem; opacity: 0.7; }

/* LENTES */
.lentes { background: var(--z-white); }
.lentes-header { display: grid; grid-template-columns: 1fr 1fr; gap: 2.5rem; align-items: end; margin-bottom: 3rem; }
.lens-cards { display: grid; grid-template-columns: repeat(3,1fr); gap: 1.25rem; }
.lens-card {
  background: var(--z-gray); border: 1px solid var(--z-gray2);
  border-radius: 10px; padding: 1.6rem;
  transition: all 0.25s; cursor: default;
}
.lens-card:hover { background: var(--z-white); border-color: rgba(27,29,181,0.3); box-shadow: 0 6px 30px rgba(27,29,181,0.08); transform: translateY(-3px); }
.lens-icon { width: 42px; height: 42px; background: var(--z-blue); border-radius: 8px; display: flex; align-items: center; justify-content: center; font-size: 1.1rem; margin-bottom: 1rem; }
.lens-card h3 { font-size: 1rem; font-weight: 700; margin-bottom: 0.4rem; }
.lens-card p { font-size: 0.84rem; color: var(--z-muted); line-height: 1.65; }
.lens-tag { display: inline-block; margin-top: 0.9rem; font-size: 0.7rem; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: var(--z-blue); background: rgba(27,29,181,0.07); padding: 3px 10px; border-radius: 100px; }

/* DIFERENCIAIS */
.dif { background: linear-gradient(rgba(10,12,40,0.82), rgba(10,12,40,0.88)), url('data:image/jpeg;base64,') center/cover no-repeat; color: var(--z-white); }
.dif .sec-title { color: var(--z-white); }
.dif-head { display: grid; grid-template-columns: 1fr 1fr; gap: 3rem; align-items: end; margin-bottom: 3.5rem; }
.dif .sec-desc { color: rgba(255,255,255,0.6); }
.dif-grid { display: grid; grid-template-columns: repeat(2,1fr); gap: 1px; background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.08); border-radius: 16px; overflow: hidden; }
.dif-item { background: rgba(255,255,255,0.03); backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); padding: 2.5rem; transition: background 0.2s; }
.dif-item:hover { background: rgba(255,255,255,0.07); }
.dif-num { font-size: 2.8rem; font-weight: 900; color: var(--z-cyan); line-height: 1; margin-bottom: 0.8rem; }
.dif-item h3 { font-size: 1.1rem; font-weight: 700; margin-bottom: 0.5rem; color: var(--z-white); }
.dif-item p { font-size: 0.88rem; color: rgba(255,255,255,0.55); line-height: 1.75; }
.cyan-line { width: 28px; height: 2px; background: var(--z-cyan); margin-bottom: 1.2rem; }

/* MARCAS */
.marcas { background: var(--z-white); text-align: center; }
.marcas-pills { display: flex; flex-wrap: wrap; gap: 0.7rem; justify-content: center; margin-top: 2.5rem; }
.m-pill { padding: 0.5rem 1.3rem; border: 1.5px solid var(--z-gray2); border-radius: 100px; font-size: 0.82rem; font-weight: 600; color: var(--z-muted); background: var(--z-gray); transition: all 0.2s; }
.m-pill:hover { border-color: var(--z-blue); color: var(--z-blue); }

/* CAROUSEL */
.deps-carousel {
  display: flex;
  gap: 1.25rem;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding-bottom: 0.5rem;
  cursor: grab;
}
.deps-carousel::-webkit-scrollbar { display: none; }
.deps-carousel:active { cursor: grabbing; }
.deps-carousel .dep {
  min-width: 340px;
  max-width: 340px;
  scroll-snap-align: start;
  flex-shrink: 0;
}
.carousel-dots {
  display: flex; gap: 6px; justify-content: center; margin-top: 1.5rem;
}
.carousel-dots .dot {
  width: 8px; height: 8px; border-radius: 50%;
  background: var(--z-gray2); border: none; cursor: pointer;
  transition: background 0.2s, transform 0.2s; padding: 0;
}
.carousel-dots .dot.active { background: var(--z-blue); transform: scale(1.3); }

/* DEPOIMENTOS V2 */
.deps { background: var(--z-gray); overflow: hidden; padding-bottom: 5rem; }
.deps-hero-title {
  text-align: center;
  margin-bottom: 3.5rem;
}
.deps-hero-title .pre {
  display: block;
  font-size: clamp(1.4rem, 3vw, 2.2rem);
  font-weight: 300;
  color: var(--z-muted);
  line-height: 1;
  margin-bottom: 0.1rem;
}
.deps-hero-title .main {
  display: block;
  font-size: clamp(3rem, 7vw, 5.5rem);
  font-weight: 900;
  color: var(--z-text);
  line-height: 1;
  letter-spacing: -0.03em;
}
.deps-hero-title .sub {
  display: block;
  font-size: clamp(2rem, 5vw, 4rem);
  font-weight: 900;
  color: var(--z-text);
  line-height: 1;
  letter-spacing: -0.03em;
}
.deps-stage {
  overflow: hidden;
  margin: 0 -5vw;
  padding: 0.5rem 5vw;
}
.deps-track {
  display: flex;
  gap: 1.25rem;
  transition: transform 0.55s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  will-change: transform;
}
.dep-card {
  flex-shrink: 0;
  width: calc((100% - 2.5rem) / 3);
  background: var(--z-white);
  border-radius: 16px;
  padding: 2rem 2rem 1.6rem;
  display: flex;
  flex-direction: column;
  gap: 0;
}
.dep-card .dep-quote {
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--z-text);
  margin-bottom: 1rem;
  line-height: 1.25;
}
.dep-card .dep-body {
  font-size: 0.88rem;
  color: var(--z-muted);
  line-height: 1.75;
  flex: 1;
  margin-bottom: 1.6rem;
}
.dep-card .dep-author-row {
  display: flex; align-items: center; gap: 0.7rem;
  padding-top: 1rem;
  border-top: 1px solid var(--z-gray2);
}
.dep-card .dep-avatar-circle {
  width: 38px; height: 38px; border-radius: 50%;
  background: linear-gradient(135deg, var(--z-blue), #4f52d3);
  display: flex; align-items: center; justify-content: center;
  font-size: 0.72rem; font-weight: 700; color: white;
  flex-shrink: 0;
  letter-spacing: 0.05em;
}
.dep-card .dep-name { font-size: 0.85rem; font-weight: 700; color: var(--z-text); }
.dep-card .dep-role { font-size: 0.75rem; color: var(--z-muted); }
.dep-card .dep-stars { color: #F4B400; font-size: 0.72rem; letter-spacing: 2px; margin-bottom: 0.9rem; }
.deps-nav {
  display: flex; justify-content: center; gap: 0.6rem;
  margin-top: 2.5rem;
}
.deps-nav button {
  width: 42px; height: 42px;
  border-radius: 8px;
  border: 1.5px solid var(--z-gray2);
  background: var(--z-white);
  cursor: pointer;
  font-size: 1rem;
  display: flex; align-items: center; justify-content: center;
  transition: border-color 0.2s, background 0.2s, color 0.2s;
  color: var(--z-text);
}
.deps-nav button:hover { border-color: var(--z-blue); background: var(--z-blue); color: white; }
@media (max-width: 768px) {
  .dep-card { width: calc(100% - 2rem); }
}
.deps-header { text-align: center; margin-bottom: 3rem; }
.deps-header .sec-desc { margin: 0 auto; text-align: center; }
.deps-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 1.5rem; }
.dep { background: var(--z-gray); border: 1px solid var(--z-gray2); border-radius: 10px; padding: 1.8rem; transition: box-shadow 0.2s; }
.dep:hover { box-shadow: 0 6px 24px rgba(27,29,181,0.08); }
.dep-stars { color: var(--z-blue); font-size: 0.82rem; letter-spacing: 2px; margin-bottom: 1rem; }
.dep p { font-size: 0.95rem; line-height: 1.7; color: var(--z-text); margin-bottom: 1.2rem; font-style: italic; font-weight: 300; }
.dep-name { font-size: 0.85rem; font-weight: 700; }
.dep-role { font-size: 0.78rem; color: var(--z-muted); }

/* CTA */
.cta { background: var(--z-blue); padding: 6rem 5vw; }
.cta-inner { max-width: 660px; margin: 0 auto; text-align: center; }
.urgency { display: inline-flex; align-items: center; gap: 7px; background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.2); padding: 0.38rem 1rem; border-radius: 100px; font-size: 0.75rem; color: rgba(255,255,255,0.9); font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; margin-bottom: 1.8rem; }
.urgency-pulse { width: 7px; height: 7px; border-radius: 50%; background: var(--z-cyan); animation: blink 1.5s infinite; }
@keyframes blink { 0%,100%{opacity:1;transform:scale(1)} 50%{opacity:0.4;transform:scale(0.7)} }
.cta .sec-title { color: var(--z-white); font-size: clamp(1.8rem,3vw,2.4rem); }
.cta-sub { color: rgba(255,255,255,0.75); font-size: 1rem; margin: 0.8rem auto 2.5rem; max-width: 460px; }

form { display: flex; flex-direction: column; gap: 0.8rem; max-width: 460px; margin: 0 auto; }
.form-row { display: flex; gap: 0.8rem; }
input[type="text"], input[type="tel"] {
  flex: 1; background: rgba(255,255,255,0.12);
  border: 1px solid rgba(255,255,255,0.25); border-radius: var(--radius);
  padding: 0.9rem 1.1rem; font-family: var(--font); font-size: 0.9rem;
  color: var(--z-white); outline: none; transition: border-color 0.2s, background 0.2s;
}
input::placeholder { color: rgba(255,255,255,0.5); }
input:focus { border-color: var(--z-cyan); background: rgba(255,255,255,0.18); }
.btn-cta { background: var(--z-white); color: var(--z-blue); padding: 1rem 2.4rem; border-radius: var(--radius); border: none; cursor: pointer; font-family: var(--font); font-size: 0.95rem; font-weight: 900; transition: background 0.2s, transform 0.15s; width: 100%; }
.btn-cta:hover { background: var(--z-gray); transform: translateY(-1px); }
#upload-label { display: flex; align-items: center; justify-content: center; gap: 8px; background: rgba(255,255,255,0.1); border: 1.5px dashed rgba(255,255,255,0.35); border-radius: var(--radius); padding: 0.85rem 1rem; cursor: pointer; font-size: 0.88rem; color: rgba(255,255,255,0.75); transition: background 0.2s, border-color 0.2s; }
#upload-label:hover { background: rgba(255,255,255,0.16); border-color: rgba(255,255,255,0.6); }
.form-note { font-size: 0.74rem; color: rgba(255,255,255,0.5); margin-top: 0.8rem; }

/* FOOTER */
footer { background: var(--z-text); padding: 2rem 5vw; display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 1rem; border-top: 1px solid rgba(255,255,255,0.06); }
.footer-brand { display: flex; align-items: center; gap: 10px; }
.footer-logo-badge { width: 32px; height: 32px; background: var(--z-blue); border-radius: 4px; display: flex; align-items: center; justify-content: center; position: relative; overflow: hidden; }
.footer-logo-badge::after { content: ''; position: absolute; bottom: -5px; left: -3px; right: -3px; height: 12px; background: var(--z-black); border-radius: 50% 50% 0 0 / 100% 100% 0 0; }
.footer-logo-text { font-size: 0.8rem; font-weight: 900; letter-spacing: 0.1em; color: var(--z-white); position: relative; z-index: 1; }
.footer-name { font-weight: 700; font-size: 0.9rem; color: var(--z-white); }
footer p { font-size: 0.75rem; color: rgba(255,255,255,0.35); }

/* ANIMATIONS */
.reveal { opacity: 0; transform: translateY(20px); transition: opacity 0.6s ease, transform 0.6s ease; }
.reveal.in { opacity: 1; transform: none; }

/* RESPONSIVE */
@media (max-width: 960px) {
  .hero-inner, .prob-grid, .lentes-header, .dif-head { grid-template-columns: 1fr; gap: 2.5rem; }
  .hero-visual { display: none; }
  .lens-cards { grid-template-columns: 1fr 1fr; }
  .dif-grid { grid-template-columns: 1fr; }
  .deps-grid { grid-template-columns: 1fr; }
  .strip-inner { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 600px) {
  .lens-cards { grid-template-columns: 1fr; }
  .form-row { flex-direction: column; }
}
